BEGIN;
CREATE TABLE IF NOT EXISTS care_tenant_memberships(tenant_id TEXT NOT NULL,user_id BIGINT NOT NULL,role TEXT NOT NULL CHECK(role IN('guardian','caregiver','care_professional','safeguarding_lead','integration_admin','tenant_admin')),active BOOLEAN NOT NULL DEFAULT true,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),PRIMARY KEY(tenant_id,user_id));
CREATE TABLE IF NOT EXISTS governed_care_plans(id BIGSERIAL PRIMARY KEY,tenant_id TEXT NOT NULL,child_ref TEXT NOT NULL,state TEXT NOT NULL CHECK(state IN('draft','review','changes_requested','approved','active','paused','closed')),version INTEGER NOT NULL DEFAULT 1,care_plan JSONB NOT NULL CHECK(jsonb_typeof(care_plan)='object'),idempotency_key TEXT NOT NULL,created_by BIGINT NOT NULL,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),UNIQUE(tenant_id,idempotency_key));
CREATE TABLE IF NOT EXISTS care_incidents(id BIGSERIAL PRIMARY KEY,tenant_id TEXT NOT NULL,care_plan_id BIGINT NOT NULL REFERENCES governed_care_plans(id),severity TEXT NOT NULL CHECK(severity IN('low','moderate','high','emergency')),incident JSONB NOT NULL,classification JSONB NOT NULL,reported_by BIGINT NOT NULL,reported_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS care_events(id BIGSERIAL PRIMARY KEY,tenant_id TEXT NOT NULL,care_plan_id BIGINT NOT NULL REFERENCES governed_care_plans(id),actor_id BIGINT NOT NULL,event_type TEXT NOT NULL,payload JSONB NOT NULL DEFAULT '{}',occurred_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS care_outbox(id BIGSERIAL PRIMARY KEY,tenant_id TEXT NOT NULL,aggregate_id BIGINT NOT NULL,event_type TEXT NOT NULL,status TEXT NOT NULL CHECK(status IN('pending','processing','succeeded','failed','dead_letter')),attempts INTEGER NOT NULL DEFAULT 0,last_error TEXT,payload JSONB NOT NULL DEFAULT '{}',created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE INDEX IF NOT EXISTS care_plan_state_idx ON governed_care_plans(tenant_id,state);CREATE INDEX IF NOT EXISTS care_outbox_status_idx ON care_outbox(status,created_at);
COMMIT;
